using DSAExperimentation.Algorithms.Sorting;using DSAExperimentation.DataStructures.Sequence;using DSAExperimentation.DataStructures.SinglyLinkedList;
namespace DSAExperimentation.Tests.LeetCodeCoverage.SortList;
public sealed partial class SortListTests { [Fact] public void SortList_Example_SortsValuesIntoNodes(){Assert.Equal([1,2,3,4],ToArray(Sort(Build([4,2,1,3]))));} private static SinglyLinkedListNode<int>? Sort(SinglyLinkedListNode<int>? head){var values=new List<int>();for(var n=head;n is not null;n=n.Next)values.Add(n.Value);var a=values.ToArray();MergeSort.Sort<int,ArrayIndexedSequence<int>>(new ArrayIndexedSequence<int>(a));return Build(a);} private static SinglyLinkedListNode<int>? Build(int[] a){var d=new SinglyLinkedListNode<int>(0);var t=d;foreach(var v in a){t.Next=new SinglyLinkedListNode<int>(v);t=t.Next;}return d.Next;} private static int[] ToArray(SinglyLinkedListNode<int>? h){var r=new List<int>();for(var n=h;n is not null;n=n.Next)r.Add(n.Value);return r.ToArray();} }
